// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points, acceptedAnswers}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    if (acceptedAnswers && (!acceptedAnswers.includes(answer) || new Set(acceptedAnswers).size !== acceptedAnswers.length ||
        !acceptedAnswers.every(index => Number.isInteger(index) && index >= 0 && index < choices.length))) {
      throw new Error('Invalid accepted answers in ' + year + '/' + grade + '/' + (index + 1));
    }
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, detailSrc, description, pixelWidth, pixelHeight}, i) => ({
      image: src, ...(detailSrc ? {detailSrc} : {}), description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(acceptedAnswers ? {acceptedAnswers} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const tokens = step === 3 ? (lessons[i].acceptedAnswers ?? [letters.indexOf(key)]).map(index => {
        const result = lessons[i].choices[index].replace(/^\[(.*)\][.]?$/, '$1');
        return letters[index] + (result ? ' · ' + result : '');
      }) : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (reviewedKey ? 'reviewed-' + grade + '.pdf' : material.answersFile ?? grade + '-answers.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2010, "8-9", [{"author":"Н. Валеева","question":"Какой репликой можно выразить полное согласие со словами собеседника?","choices":["<em>Не скажи!</em>","<em>Не говори!</em>","<em>Не болтай!</em>","<em>Помолчи!</em>","<em>Рассказывай!</em>"],"key":"Б","review":["Реплика согласия","Представь ответ на жалобу, с которой ты целиком согласен. В разговоре смысл такой реплики может отличаться от буквального.","«Не говори!» в ответ на замечание выражает согласие: «Да, именно так». «Не скажи!» обычно выражает сомнение или возражение."]},{"author":"Б. Иомдин","question":"С какого знака препинания может начинаться предложение?","choices":["точка","запятая","дефис","кавычка","двоеточие."],"key":"Г","review":["Знак в начале предложения","Вспомни, как записывают прямую речь или самостоятельную цитату. Какой знак может открывать её?","Предложение, начинающееся с цитаты, может начинаться с открывающей кавычки. Дефис, в отличие от тире, для начала реплики не используется."]},{"author":"Н. Валеева","question":"Какое из данных ниже заимствованных слов не содержит приставки латинского происхождения <em>суб</em>-?","choices":["<em>субтитр</em>","<em>субтропики</em>","<em>субординация</em>","<em>субмарина</em>","<em>суббота</em>."],"key":"Д","review":["Начальная часть заимствований","Сравни «субмарина» с другими словами, где начальная часть обозначает нахождение ниже или при другом объекте.","В слове «суббота» начальные буквы принадлежат заимствованному корню. Это название дня недели восходит к «саббат», а латинской приставки в нём нет."]},{"author":"Е. Кац","question":"Какое обращение по смыслу сильно отличается от остальных?","choices":["сеньор","мистер","герр","мисс","пан."],"key":"Г","review":["Смысл обращения","Проверь, к кому обращаются каждым из этих заимствованных слов. Одно указывает на другую группу адресатов.","«Сеньор», «мистер», «герр» и «пан» — обращения к мужчинам. «Мисс» — обращение к женщине, традиционно незамужней."]},{"author":"Н. Валеева","question":"Какое из этих существительных не образует устойчивого сочетания с прилагательным <em>снежный</em>?","choices":["<em>баба</em>","<em>барс</em>","<em>королева</em>","<em>медведь</em>","<em>человек</em>."],"key":"Г","review":["Устойчивое сочетание о снеге","Вспомни сказочный образ, название гималайского зверя и существо из рассказов о горных экспедициях.","Есть «снежная баба», «снежный барс», «Снежная королева», «снежный человек». «Снежный медведь» устойчивого названия не образует."]},{"author":"О. Шеманаева","question":"Какое из этих слов обозначает человека?","choices":["<em>усилитель</em>","<em>ускоритель</em>","<em>учредитель</em>","<em>удлинитель</em>","<em>утеплитель</em>."],"key":"В","review":["Действие и человек","Попробуй объяснить каждое слово через глагол. Ищи того, кто создаёт организацию или начинает её деятельность.","«Учредитель» — человек или организация, учреждающие что-либо. Другие варианты обычно называют устройства, материалы или их детали."]},{"author":"Н. Валеева","question":"Какое из этих слов ни в одном из значений не имеет отношения к кулинарии?","choices":["<em>начинить</em>","<em>подсластить</em>","<em>поперчить</em>","<em>сдобрить</em>","<em>умаслить</em>."],"key":"Д","review":["Слово и кулинария","Сопоставь глаголы с действиями при готовке — добавить начинку, сахар, перец или сдобу.","Эти действия выражают «начинить», «подсластить», «поперчить», «сдобрить». «Умаслить» в обычном употреблении значит задобрить человека, добиться его расположения."]},{"author":"И. Рубанов","question":"В математических текстах нередко встречается оборот <em>не ум...ляя общности</em>. Какая буква стоит в нём там, где мы поставили многоточие?","choices":["<em>а</em>","<em>е</em>","<em>и</em>","<em>о</em>","<em>ы</em>."],"key":"А","review":["Оборот из математики","Определи, идёт ли речь о просьбе или об уменьшении чего-либо. Слово «общность» обозначает охват случаев.","Пишут «не умаляя общности», то есть не уменьшая общности рассуждения. В «умалять» пишется «а», как в слове «малый»."]},{"author":"С. Бурлак","question":"В каком из глаголов тот же корень, что в слове <em>губа</em>?","choices":["<em>загубить</em>","<em>пригубить</em>","<em>погубить</em>","<em>сгубить</em>","во всех."],"key":"Б","review":["Родство со словом «губа»","Сравни значения действий. В каком случае действие выполняют именно губами?","«Пригубить» значит слегка отпить, коснувшись жидкости губами. «Загубить», «погубить» и «сгубить» связаны с гибелью."]},{"author":"И. Иткин","question":"В каких падежах существительное <em>уж</em> ‘неядовитая змея’ можно перепутать с наречием?","choices":["в именительном и дательном","в дательном и винительном","в именительном и предложном","в дательном и предложном","в именительном, винительном и предложном."],"key":"В","review":["Формы слова «уж»","Просклоняй название змеи и вспомни краткое «уж» со значением «уже». Сравни написания.","Именительный «уж» совпадает с «уж». В предложном падеже «об уже» форма «уже» совпадает с наречием. Винительный — «ужа», дательный — «ужу»."]},{"author":"Е. Вельмезова","question":"Даны слова: <em>горящий</em>, <em>горячий</em>, <em>горючий</em>, <em>горевший</em>, <em>горюющий</em>. Сколько среди них причастий от глагола <em>гореть</em>?","choices":["одно","два","три","четыре","пять."],"key":"Б","review":["Причастия от «гореть»","Спрашивай «который горит?» или «который горел?». Слово от другого глагола в счёт не входит.","«Горящий» и «горевший» — причастия от «гореть». «Горюющий» образовано от «горевать», а «горячий» и «горючий» — прилагательные."]},{"author":"О. Баженова","question":"Какое из данных словосочетаний по смыслу устроено не так, как остальные?","choices":["<em>хитрый на выдумки</em>","<em>скупой на слова</em>","<em>щедрый на посулы</em>","<em>падкий на лесть</em>","<em>быстрый на расправу</em>."],"key":"Г","review":["Куда направлено действие","Проверь, что делает сам человек в каждом примере и что он получает от окружающих.","«Падкий на лесть» — восприимчивый к чужой лести. В остальных сочетаниях речь о собственных выдумках, словах, обещаниях или поступках человека."]},{"author":"Б. Иомдин и Ю. Халеева","question":"Какое слово не однокоренное с остальными?","choices":["<em>восход</em>","<em>расход</em>","<em>лиходей</em>","<em>снисходительность</em>","<em>ухажёр</em>."],"key":"В","review":["Похожие корни","Попробуй объяснить каждое слово через движение. Отдельно проверь слово о человеке, который причиняет зло.","«Восход», «расход», «снисходительность» и «ухажёр» связаны с «ходить». «Лиходей» обозначает того, кто творит лихо, и связан с «делать»."]},{"author":"Л. Фёдорова","question":"В какой паре выражения противоположны по смыслу?","choices":["<em>взять быка за рога — тянуть кота за хвост</em>","<em>намотать себе на ус — зарубить себе на носу</em>","<em>развесить уши — вешать лапшу на уши</em>","<em>щёлкать клювом — клевать носом</em>","<em>пускать пыль в глаза — втирать очки</em>."],"key":"А","review":["Устойчивые противоположности","Сравни первое действие в каждой паре со вторым. Ищи противопоставление решительности и затягивания дела.","«Взять быка за рога» значит решительно взяться за дело. «Тянуть кота за хвост» — медлить и откладывать решение."]},{"author":"И. Иткин","question":"Дав маленькой Барби Бэнкс подержать волшебный градусник, Мэри Поппинс прочитала на нём: «<em>... избалованна</em>». Как правильно заполнить пропуск?","choices":["только <em>До́нельзя</em>","только <em>Доне́льзя</em>","только <em>Донельзя́</em>","возможны варианты <em>До́нельзя</em> и <em>Доне́льзя</em>","возможны варианты <em>До́нельзя</em> и <em>Донельзя́</em>."],"key":"Б","review":["Ударение при усилении","Градусник показывает, что ребёнок очень избалован. Вспомни словарное произношение наречия со значением «до предела».","Правильно «доне́льзя избалованна». Ударение падает на «е»."]},{"author":"О. Шеманаева","question":"В каком предложении предлог кроме значит не то же, что в остальных?","choices":["Все улыбнулись, кроме лейтенанта. (Э. Г. Казакевич)","Кроме блюд и соусников, на столе стояло множество горшочков. (Н. В. Гоголь)","Кроме старика, в этот день приходило к нам ещё двое. (А. П. Чехов)","Теперь слышались, кроме грачиных, человеческие голоса. (А. Н. Толстой)","Быть может, кроме права на улыбку, мы должны признать друг за другом и право на сдвинутые брови. (В. П. Аксёнов)"],"key":"А","review":["Два значения «кроме»","Подставь «за исключением» или «помимо». Проверь, о ком сказано, что он не совершил действие.","В первой цитате лейтенант не улыбнулся: он исключён. В остальных «кроме» прибавляет что-либо к уже названному."]},{"author":"А. Пиперски","question":"Как правильно?","choices":["<em>по-добру, по-здорову</em>","<em>подобру-поздорову</em>","<em>по добру</em>, <em>по здорову</em>","<em>по-добру — по-здорову</em>","<em>подобру, поздорову</em>."],"key":"Б","review":["Парное наречие","Вспомни устойчивую фразу о том, чтобы уйти мирно и без неприятностей.","Сочетание пишется «подобру-поздорову». Обе части слитны внутри, между ними стоит дефис."]},{"author":"С. Переверзева","question":"От какого слова образовано прилагательное <em>стоический</em>?","choices":["<em>стоить</em>","<em>стоять</em>","<em>стойкий</em>","<em>стоик</em>","<em>стоя</em>."],"key":"Г","review":["История прилагательного","Вспомни название философской школы, для которой важна выдержка перед испытаниями.","«Стоический» образовано от «стоик» — последователь стоицизма. Отсюда переносное значение «стойкий, выдержанный»."]},{"author":"С. Переверзева","question":"Кто, согласно легенде, изобрёл способ наглухо закупоривать стеклянную трубку?","choices":["<em>Амон</em>","<em>Бахус</em>","<em>Варфоломей</em>","<em>Гермес</em>","<em>Давид</em>."],"key":"Г","review":["Имя в слове о герметичности","Ищи имя, которое слышится в слове «герметичный». Оно связано со старинными легендами об алхимиках.","Название связано с Гермесом Трисмегистом. Именно ему легенда приписывает способ герметично закрывать сосуды."]},{"author":"Н. Валеева","question":"Чтобы школьники лучше усвоили одно орфографическое правило, учителя иногда предлагают им запомнить слово <em>веломотокинофототелерадиомонтёр</em>. А какой из данных ниже элементов можно ещё добавить в это слово?","choices":["<em>горе</em>-","<em>вице</em>-","<em>нео</em>-","<em>макси</em>-","<em>экс</em>-."],"key":"В","review":["Соединение частей слова","В многокомпонентном слове все первые части присоединены слитно. Проверь, для какой из предложенных частей подходит то же правило.","«Нео-» обычно пишется слитно с последующей частью, как в «неореализм». Поэтому его можно присоединить по тому же правилу."]},{"author":"В. Черванёва","question":"Какое из этих слов с исторической точки зрения не содержит приставки?","choices":["<em>сутолока</em>","<em>судорога</em>","<em>сумерки</em>","<em>супруг</em>","<em>суета</em>."],"key":"Д","review":["Историческая приставка «су»","Сравни «сумерки» с «меркнуть» и «супруг» с «запрягать». В одном из слов похожее начало принадлежит корню.","В «суете» часть «су-» не отделяется: слово связано с «суе», «суе́тный». В остальных словах исторически выделялась приставка «су-»."]},{"author":"С. Бурлак","question":"Вася узнал, что есть такая звезда — Альфа Центавра, и решил написать о ней фантастический роман. Итак, его герои полетят:","choices":["<em>к Альфе Центавра</em>","<em>к Альфе Центавре</em>","<em>к Альфа Центавре</em>","<em>к Альфа Центавра</em>","<em>к Альфа Центавру</em>."],"key":"А","review":["Падеж названия звезды","Подумай, какую часть названия изменяет предлог «к». «Центавра» уже отвечает на вопрос «чего?».","«Альфа» становится «Альфе», а зависимый родительный «Центавра» сохраняется. Получается «к Альфе Центавра»."]},{"author":"О. Едемская и И. Иткин","question":"В древнерусском языке было слово <em>суп</em>, означавшее хищную птицу — коршуна или грифа. Данные современного русского языка позволяют сделать вывод о том, что этой птице приписывали:","choices":["исключительное корыстолюбие","очень высокую скорость полёта","мрачный взгляд","жертвенную любовь к птенцам","способность воскресать после смерти."],"key":"В","review":["Слово от названия птицы","Вспомни, что человек делает, когда насупится. Эта реакция даёт подсказку к представлению о птице.","«Насупиться» означает нахмуриться, принять угрюмый вид. В этимологии, принятой в задаче, его связывают с названием птицы «суп» и её мрачным взглядом."]},{"author":"А. Пиперски","question":"Вот стихотворение Д. Д. Минаева:\n<em>Дав(0) кричал я: «Уто(+),\nКогда на Лизе не женюсь!»?\nИ вот теперь твой муж, смо(3),\nК ка(…)евши, размышляет:\n«Кто женится, чёрт побери,\nТот в сумас(6)вии блуждает».</em>\nЧто должно стоять на месте многоточия?","choices":[".",",","−","8","9"],"key":"В","review":["Знаки в стихотворении","Прочитай символы словами. Например, «смо(3)» даёт «смотри». Какое название знака позволит узнать слово «камин»?","Из «К ка(−)евши» получается «к камину севши»: название знака «минус» распределяется между словом «камину» и началом слова «севши»."]},{"author":"Б. Иомдин","question":"<em>Идёт-<u>гудёт</u> Зелёный Шум</em>...\nВ этом отрывке из стихотворения Н. А. Некрасова подчёркнутый глагол, ныне устаревший, означает то же, что <em>гудеть</em>. А как выглядела его неопределённая форма?","choices":["<em>гудеть</em>","<em>гудёть</em>","<em>гудить</em>","<em>гуйти</em>","<em>густи</em>."],"key":"Д","review":["Старинный глагол","Сравни «гудёт» с парами «ведёт — вести» и «кладёт — класть». В инфинитиве согласный может измениться.","У Некрасова форма «гудёт» восходит к старому инфинитиву «густи». Он обозначал то же действие, что современное «гудеть»."]},{"author":"Н. Валеева","question":"Даны глаголы: <em>бежать, идти, лететь, ползти</em>. Сколько из них являются двувидовыми, то есть могут употребляться как глаголы и совершенного, и несовершенного вида?","choices":["ни одного","один","два","три","все четыре."],"key":"Б","review":["Два вида у глагола движения","Попробуй употребить каждый глагол как длительное движение и как однократный завершённый поступок.","«Бежать по дороге» — несовершенный вид. «Удалось бежать из плена» значит удалось совершить побег, это совершенный вид. Из списка двувидовой только «бежать»."]},{"author":"А. Беляев","question":"В русском языке есть поговорка о ситуации, когда люди, не слушая друг друга, говорят каждый о своём. В этой поговорке упоминаются два мужских имени. Какая из приведённых ниже пар составлена из иностранных аналогов этих имён?","choices":["<em>Лёлек и Болек</em>","<em>Том и Джерри</em>","<em>Чип и Дейл</em>","<em>Бивис и Баттхэд</em>","<em>Джонсон и Джонсон</em>."],"key":"Б","review":["Имена из поговорки","Вспомни фразу «Я ему про Фому, а он мне про Ерёму». Сопоставь эти имена с именами персонажей.","Фома соответствует Томасу, сокращённо Том. Ерёма восходит к тому же имени, что Иероним и английское Jerome, от которого возможно Jerry. Подходят Том и Джерри."]},{"author":"В. Люсина","question":"Даны словосочетания на каталанском языке (каталанский язык — один из романских языков) и их переводы на русский язык:\n<em>la lloba muda</em> — немая волчица,\n<em>la amiga cega</em> — слепая подруга,\n<em>el nebot mut</em> — немой племянник,\n<em>el amic enfadat</em> — обиженный друг\nКак будет по-каталански: <em>обиженная племянница, слепой волк</em>?","choices":["la nebota enfadata, el llob ceg","la enfadada neboda, el cec llop","la neboda enfadada, el llop cec","la neboda enfadata, el llob cec","el neboda enfadata, el llop cega."],"key":"В","review":["Род слов по-каталански","Сопоставь мужское и женское окончания. Проверь артикль и порядок существительного с прилагательным.","«Племянница» и «обиженная» дают «la neboda enfadada». Формы мужского рода от «lloba» и «cega» — «el llop cec»: на конце согласные оглушаются."]},{"author":"А. Пиперски","question":"В слове <em>параграф</em> три звонких согласных звука: [р], [г], [р]. А сколько звонких согласных во фразе <em>Я вряд ли смогу оплатить проезд</em>?","choices":["семь","восемь","девять","десять","одиннадцать."],"key":"В","review":["Звонкие согласные во фразе","Считай звуки, а не буквы. В «я» слышится [й], а на конце «проезд» шумные согласные оглушаются.","Получаются [й] в «я», [в], [р’] в «вряд», [л’] в «ли», [м], [г] в «смогу», [л] в «оплатить», [р], [й] в «проезд». Всего девять."]},{"author":"Е. Муравенко","question":"Нарицательные существительные женского рода в именительном падеже единственного числа могут оканчиваться:\n1) на гласные буквы <em>-а/-я</em>,\n2) на другие гласные (не <em>-а/-я</em>),\n3) на букву <em>-ь</em>,\n4) на согласные буквы.\nВыберите верные утверждения.","choices":["только 1","только 1 и 3","только 1, 2 и 3","только 1, 3 и 4","1, 2, 3 и 4."],"key":"Д","review":["Конец слова женского рода","Проверь не только склоняемые слова, но и заимствования, форма которых не меняется.","«Мама» оканчивается на «а», «леди» — на другую гласную, «мышь» — на «ь», «мисс» — на согласную. Возможны все четыре случая."]}], {"year":2010,"grade":"8-9","tasksFile":"8-9.pdf","answersFile":"8-9-answers.pdf","sourceUrl":"https://konkurs43.ru/rm/task2010.zip"}), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
